function initLang(code) {
  LANG = ORDER.includes(code) ? code : 'ru'
  document.documentElement.lang = LANG
}
const lang = () => LANG
const hasKey = (k) => k in D

function t(key, params) {
  const row = D[key]
  let s = row ? row[ORDER.indexOf(LANG)] || row[1] : key
  if (params) s = s.replace(/\{(\w+)\}/g, (m, k) => (params[k] !== undefined ? params[k] : m))
  return s
}

function applyI18n() {
  initLang(S ? S.settings.language : LANG)
  document.querySelectorAll('[data-i18n]').forEach((e) => (e.textContent = t(e.dataset.i18n)))
  document.querySelectorAll('[data-i18n-aria]').forEach((e) => e.setAttribute('aria-label', t(e.dataset.i18nAria)))
  document.querySelectorAll('[data-label-i18n]').forEach((sel) => {
    sel.dataset.label = t(sel.dataset.labelI18n)
    const lab = sel.parentElement && sel.parentElement.querySelector('label')
    if (lab && sel.dataset.enh) lab.textContent = sel.dataset.label
  })
  if (typeof browseSync === 'function' && typeof $ === 'function' && $('#bSort')) browseSync()
}
